<style lang="scss" src="./gms-new-report-modal.scss"></style>

<script>
import {
  destroyModalRootContent,
  ensureModalRoot,
} from "../../util/ensure-modal-root";
import { Component, Prop, Vue } from "vue-property-decorator";
import Icon from "../icon/icon";
import { IconShape } from "../icon/icon.constants";
import Button from "../button/button";
import { ButtonMode } from "../button/button.constants";
import { MountingPortal } from "portal-vue";
import Select from "../select/select";
import ScrollView from "../scroll-view/scroll-view";
import { FilterType } from "./gms-new-report-modal.constants";
import validateReportFilters from "../../util/validate-reporting-filters";


const Pages = {
  FILTERS: "filters",
  VISIBILITY: "visibility",
};

/**
 * Modal for generating a new report
 */
@Component({
  components: {
    Icon,
    Button,
    MountingPortal,
    Select,
    ScrollView,
  },
})
export default class GmsNewReportModal extends Vue {
  /**
   * This is executed when the user has completed the form. This allows you to
   * control whether or not the report successfully closes. It will pass the
   * state of the filled out fields the user completed, this method can validate
   * the inputs.
   *
   * If invalid, return false and update the "error" property.
   *
   * If valid, return true and this modal will close automatically.
   */
  @Prop({ type: Function }) onSave;
  /**
   * This is an error message to display to the user. You can set this in
   * response to the save event for validation purposes.
   */
  @Prop({ type: String }) error;
  /**
   * Configure the dropdowns for the filters the user can add.
   * You configure the first column to be the filter types, then you add
   * configurations available for each filter type.
   *
   * {
   *   types: [
   *    {
   *      label: string,
   *      value: FilterType (DATE, STRING, NUMBER, DROPDOWN, MULTI_SELECT, UUID, NONE)
   *    },
   *    {
   *      label: string,
   *      value: FilterType
   *    },
   *    ...
   *   ],
   *   config: {
   *     // Key matches a value found in "types"
   *     value: [
   *       // Supports two dropdown configurations for the next two selections
   *       {
   *         placeholder: string,
   *         options: [{label, value}, {label, value}, {label, value}, ...]
   *       },
   *       {
   *         placeholder: string,
   *         options: [{label, value}, {label, value}, {label, value}, ...]
   *       },
   *     ],
   *
   *     // Key matches a value found in "types"
   *     value: [
   *       // Supports two dropdown configurations for the next two selections
   *       {
   *         placeholder: string,
   *         options: [{label, value}, {label, value}, {label, value}, ...]
   *       },
   *       {
   *         placeholder: string,
   *         options: [{label, value}, {label, value}, {label, value}, ...]
   *       },
   *     ],
   *
   *     // repeat for each value present in "types"
   *   }
   * }
   */
  @Prop({
    type: Object,
    default: () => ({ types: [], config: {} }),
  })
  filterConfig;
  /**
   * Provide dropdown options for the focus setting of the report.
   * Include hasInvitation: true to the option to display invitation information
   * to the user.
   * {
   *   placeholder: string,
   *   options: [
   *     { label: string, value; any, hasInvitation: boolean },
   *     { label: string, value; any, hasInvitation: boolean },
   *     { label: string, value; any, hasInvitation: boolean },
   *     etc...
   *   ]
   * }
   */
  @Prop({
    type: Object,
    default: () => ({ placeholder: "", options: [] }),
  })
  visibilityConfig;
  /**
   * Provide dropdown options for the visibility setting of the report.
   * Include hasInvitation: true to the option to display invitation information
   * to the user.
   * {
   *   placeholder: string,
   *   options: [
   *     { label: string, value; any, hasInvitation: boolean },
   *     { label: string, value; any, hasInvitation: boolean },
   *     { label: string, value; any, hasInvitation: boolean },
   *     etc...
   *   ]
   * }
   */
  @Prop({
    type: Object,
    default: () => ({ placeholder: "", options: [] }),
  })
  focusConfig;
  @Prop({ type: Boolean, default: true }) showRecordCount;
  /** Number of available records with the given filter configuration */
  @Prop({ type: Number }) recordCount;
  /**
   * The list of emails the user is sharing their email with. This list should
   * be updated everytime the user clicks the invite button.
   *
   * [
   *   title: string;
   *   email: string;
   * ]
   */
  @Prop({ type: Array, default: () => [] })
  emailInvitations;
  /**
   * This is the root modal element the menu resides in to render floating above
   * all the other elements in the DOM.
   */
  modalRoot = null;

  /**
   * Stores our filter data
   * { type: FilterType, value1: any, value2: any }[]
   */
  filters = [];
  /** User specified report name */
  reportName = "";
  /** User specified focus */
  focusValue = "";
  /** User Specified visibility */
  visibilityValue = "";
  /** The email the user has input into the input box */
  emailInvitationValue = "";
  /** Current step in the saving process the user is at */
  page = Pages.FILTERS;
  /** Label for the save button */
  saveButtonLabel = "Save Report";

  // Constants
  IconShape = IconShape;
  ButtonMode = ButtonMode;
  Pages = Pages;

  beforeMount() {
    // HACK: MountingPortal spawns mass duplicates. So as Thanos once said:
    //       Fine. I'll do it myself
    destroyModalRootContent("Menu");
    this.modalRoot = ensureModalRoot();

    if (!this.modalRoot) {
      console.warn("Could not establish modal root for floating componentry");
      return;
    }

    window.addEventListener("resize", this.handleResize);
  }

  beforeDestroy() {
    window.removeEventListener("resize", this.handleResize);
  }

  handleResize() {
    this.$forceUpdate();
  }

  /**
   * HACKY HACKS: Due to vue portal having it's own set of issues and we handle
   * its DOM disposal manually, this causes certain scenarios to throw errors
   * from the MountingPortal component. So, we just absorb those issues here for
   * now until better solutions can be discovered or Vue3 is used with better
   * native made portals.
   */
  errorCaptured(err, vm, info) {
    if (info === "beforeDestroy hook") {
      return false;
    }
  }

  handleCloseOutside(e) {
    if (e.target !== this.$refs.container) return;
    this.handleClose();
    e.stopPropagation();
    e.preventDefault();
  }

  // Computed properties
  get modalRootId() {
    return `#${this.modalRoot.id}`;
  }

  get containerStyle() {
    return {
      height: `${window.innerHeight}px`,
    };
  }

  get isInvitationOption() {
    const option = this.visibilityConfig.options.find(
      (opt) => opt.value === this.visibilityValue
    );
    if (option) return option.hasInvitation;

    return false;
  }

  getFilterValues(filterIndex, configIndex) {
    const filter = this.filters[filterIndex];
    const config = this.filterConfig.config[filter.ref];

    if (config) {
      const configColumn = config[configIndex];

      if (configColumn) {
        return configColumn.options || [];
      }
    }

    return [];
  }

  getFilterPlaceholder(filterIndex, configIndex) {
    const filter = this.filters[filterIndex];
    const config = this.filterConfig.config[filter.ref];

    if (config) {
      const configColumn = config[configIndex];

      if (configColumn) {
        return configColumn.placeholder || void 0;
      }
    }

    return void 0;
  }

  get emailValues() {
    return this.emailInvitations.map((e) => {
      return {
        label: e.title,
        value: e.email,
      };
    });
  }

  validateFilters() {
    const { isValid, error } = validateReportFilters(this.filters)

    if (error) {
      this.error = error;
    }

    return !!isValid;
  }

  validateVisibility() {
    return true;
  }

  isNumber(index) {
    const type = this.filters[index].condition.type || this.filters[index].type;

    return type === FilterType.NUMBER;
  }

  isString(index) {
    const type = this.filters[index].condition.type || this.filters[index].type;

    return type === FilterType.STRING || type === FilterType.UUID;
  }

  isDate(index) {
    const type = this.filters[index].condition.type || this.filters[index].type;

    return type === FilterType.DATE;
  }

  isDropdown(index) {
    const type = this.filters[index].condition.type || this.filters[index].type;

    return type === FilterType.DROPDOWN;
  }

  isMultiSelect(index) {
    const type = this.filters[index].condition.type || this.filters[index].type;

    return type === FilterType.MULTI_SELECT;
  }

  // Handlers

  handleClose() {
    this.page = Pages.FILTERS;
    this.reportName = "";
    this.filters = [];
    this.focusValue = "";
    this.visibilityValue = "";

    /**
     * Emits when the user intends to close this modal
     *
     * @event close
     */
    this.$emit("close");
  }

  handleDelete(index) {
    this.filters.splice(index, 1);
    /**
     * Emits when the user changes the filters applied to the report
     *
     * @event filters
     */
    this.$emit("filters", this.filters);
  }

  handleReportNameInput() {
    /**
     * Emits when the user inputs in the report name field
     *
     * @event filters
     */
    this.$emit("reportNameChange", this.reportName);
  }

  handleFocusChange(value) {
    if (this.focusValue !== value) {
      this.focusValue = value;
      /**
       * Emits when the user changes the focus value
       *
       * @event focusChange
       */
      this.$emit("focusChange", value);

      // Clear filters
      this.filters = [];
      /**
       * Emits when the user changes the filters applied to the report
       *
       * @event filters
       */
      this.$emit("filterChange", this.filters);
    }
  }

  handleVisibilityChange(value) {
    this.visibilityValue = value;

    if (value === "share") {
      this.saveButtonLabel = "Save and Share Report";
    } else {
      this.saveButtonLabel = "Save Report";
    }
    /**
     * Emits when the user changes the visibility value
     *
     * @event focusChange
     */
    this.$emit("visibilityChange", value);
  }

  handleAddFilter() {
    this.filters.push({
      type: this.filterConfig.types[0].type,
      ref: this.filterConfig.types[0].value,
      header_ref: this.filterConfig.types[0].header_ref,
      condition: {
        label: void 0,
        func: void 0,
      },
      filterValue: void 0,
    });
  }

  handleClearFilters() {
    this.filters = [];
    /**
     * Emits when the user changes the filters applied to the report
     *
     * @event filters
     */
    this.$emit("filterChange", this.filters);
  }

  handleFilterTypeChange(index, value, item) {
    this.filters[index].type = item.type;
    this.filters[index].ref = item.value;
    this.filters[index].header_ref = item.header_ref;
    this.$forceUpdate();
    /**
     * Emits when the user changes the filters applied to the report
     *
     * @event filterChange
     */
    this.$emit("filterChange", this.filters);
  }

  handleConditionChange(index, value, condition) {
    this.filters[index].condition.label = value;
    this.filters[index].condition.func = condition.func;
    this.filters[index].condition.type = condition.type;
    this.$forceUpdate();
    /**
     * Emits when the user changes the filters applied to the report
     *
     * @event filterChange
     */
    this.$emit("filterChange", this.filters);
  }

  handleStringInput(e, index) {
    this.filters[index].filterValue = e.target.value;
    /**
     * Emits when the user inputs the string field
     *
     * @event stringInput
     *
     */
    this.$emit("stringInput", e.target.value, index);

    /**
     * Emits when the user changes the filters applied to the report
     *
     * @event filterChange
     */
    this.$emit("filterChange", this.filters);
  }

  handleNumberInput(e, index) {
    this.filters[index].filterValue = e.target.value;
    /**
     * Emits when the user inputs the number field
     *
     * @event numberInput
     */
    this.$emit("numberInput", e.target.value, index);
    /**
     * Emits when the user changes the filters applied to the report
     *
     * @event filterChange
     */
    this.$emit("filterChange", this.filters);
  }

  handleDatePick(e, index) {
    this.filters[index].filterValue = e.target.value;
    /**
     * Emits when the user picks a date
     *
     * @event datePick
     */
    this.$emit("datePick", e.target.value, index);
    /**
     * Emits when the user changes the filters applied to the report
     *
     * @event filterChange
     */
    this.$emit("filterChange", this.filters);
  }

  handleSelectOption(index, value) {
    this.filters[index].filterValue = value;
    /**
     * Emits when the user changes the filters applied to the report
     *
     * @event filterChange
     */
    this.$emit("filterChange", this.filters);
  }

  handleSelectionMultiOptions(index, values) {
    this.filters[index].filterValue = values;
    /**
     * Emits when the user changes the filters applied to the report
     *
     * @event filterChange
     */
    this.$emit("filterChange", this.filters);
  }

  handleNext() {
    switch (this.page) {
      case Pages.FILTERS:
        if (this.validateFilters()) {
          this.page = Pages.VISIBILITY;
        }
        break;

      case Pages.VISIBILITY:
        if (this.validateVisibility()) {
          if (
            this.$props.onSave({
              reportName: this.reportName,
              focus: this.focusValue,
              visibility: this.visibilityValue,
              filters: this.filters.slice(0),
              emailInvitations: this.isInvitationOption
                ? this.emailInvitations
                : [],
            })
          ) {
            const config = {
              reportName: this.reportName,
              focus: this.focusValue,
              visibility: this.visibilityValue,
              filters: this.filters.slice(0),
              emailInvitations: this.isInvitationOption
                ? this.emailInvitations
                : [],
            };
            /**
             * Emits when the user saves the report
             *
             * @event saveReport
             */
            this.$emit("saveReport", config);
            this.handleClose();
          }
        }
        break;
    }
  }

  handleCancel() {
    switch (this.page) {
      case Pages.FILTERS:
        this.handleClose();
        break;

      case Pages.VISIBILITY:
        this.page = Pages.FILTERS;
        break;
    }
  }

  handleEmailInviteChange(value) {
    this.emailInvitationValue = value;
  }

  handleInvite() {
    /**
     * Emits when the user clicks the invite button after entering an email of
     * someone to invite.
     */
    this.$emit("invite", this.emailInvitationValue);
    this.emailInvitationValue = "";
  }

  getFilterKey(header_ref, i) {
    return `${header_ref}_${i}`;
  }

  /**
   * Based on the given filter, return the value of the corresponding Filter Type field
   *
   * @default string the first filter type in the list of filter types if none is supplied
   */
  getInitialFilterType(filter) {
    return (
      this.filterConfig.types.find((type) => type.value === filter.header_ref)
        ?.value || this.filterConfig.types[0].value
    );
  }

  /**
   * Based on the given filter, return the value of the corresponding Condition field
   *
   * @default string the first condition in the list of conditions is none is supplied
   */
  getInitialCondition(filter) {
    return (
      this.filterConfig.config[filter.header_ref]?.[0]?.options?.find(
        (option) => option.value === filter?.condition?.label
      )?.value ||
      this.filterConfig.config[filter.header_ref]?.[0]?.options[0]?.value
    );
  }
}
</script>

<template>
  <MountingPortal :mountTo="modalRootId" append>
    <div
      class="GmsNewReportModal"
      :style="containerStyle"
      ref="container"
      @click="handleCloseOutside"
    >
      <!-- Filters Page -->
      <div v-if="page === Pages.FILTERS" class="GmsNewReportModal__Content">
        <div class="GmsNewReportModal__Top">
          <div class="GmsNewReportModal__Left">
            <h2>Create a New Report</h2>
            <h3 v-if="error">{{ error }}</h3>
          </div>
          <div class="GmsNewReportModal__Right">
            <Icon
              class="GmsNewReportModal__Close"
              :shape="IconShape.CLOSE"
              :size="24"
              @click="handleClose"
            />
          </div>
        </div>
        <div class="GmsNewReportModal__Center">
          <ScrollView>
            <div class="GmsNewReportModal__Row">
              <div class="GmsNewReportModal__RowHead">
                <div class="GmsNewReportModal__Title">Report Title</div>
              </div>
              <div class="GmsNewReportModal__RowBody">
                <input
                  class="GmsNewReportModal__Input"
                  type="text"
                  placeholder="New Custom Report"
                  @input="handleReportNameInput"
                  v-model="reportName"
                />
                <div class="GmsNewReportModal__Title">Focus is</div>
                <Select
                  key="focus"
                  search
                  :label="focusConfig.placeholder"
                  :value="focusValue"
                  :items="focusConfig.options"
                  @select="handleFocusChange"
                />
              </div>
              <div class="GmsNewReportModal__RowFoot" />
            </div>
            <div
              class="GmsNewReportModal__Row"
              v-for="(filter, i) in filters"
              :key="i"
            >
              <button
                class="GmsNewReportModal__Row-Delete"
                @click="handleDelete(i)"
                aria-label="Delete Filter"
              >
                <Icon :shape="IconShape.CLOSE" :size="24" />
              </button>
              <div class="GmsNewReportModal__Row-Title" v-if="i === 0">
                Where
              </div>
              <div class="GmsNewReportModal__Row-Title" v-else>And</div>
              <!-- Filter Type -->
              <Select
                class="GmsNewReportModal__Row-Menu"
                search
                :label="getInitialFilterType(filter)"
                :value="getInitialFilterType(filter)"
                :items="filterConfig.types"
                @select="
                  (value, item) => handleFilterTypeChange(i, value, item)
                "
              />

              <!-- Filter Condition -->
              <Select
                class="GmsNewReportModal__Row-Menu"
                search
                :key="getFilterKey(filter.header_ref, i)"
                :label="getFilterPlaceholder(i, 0)"
                :value="getInitialCondition(filter, i)"
                :items="getFilterValues(i, 0)"
                :showSearch="true"
                @select="
                  (value, condition) =>
                    handleConditionChange(i, value, condition)
                "
              />

              <!-- Filter Value -->
              <input
                v-if="isString(i)"
                class="GmsNewReportModal__Row-Input"
                type="text"
                placeholder="input a value"
                @input="handleStringInput($event, i)"
              />
              <input
                v-else-if="isNumber(i)"
                class="GmsNewReportModal__Row-Input"
                type="number"
                placeholder="input a value"
                @input="handleNumberInput($event, i)"
              />
              <input
                v-else-if="isDate(i)"
                class="GmsNewReportModal__Row-Input GmsNewReportModal__Row-Input--DatePicker"
                type="date"
                placeholder="input a value"
                @change="handleDatePick($event, i)"
              />
              <Select
                v-else-if="isDropdown(i)"
                class="GmsNewReportModal__Row-Dropdown"
                search
                :label="getFilterPlaceholder(i, 1)"
                :items="getFilterValues(i, 1)"
                :value="filter.filterValue"
                @select="(value) => handleSelectOption(i, value)"
              />
              <Select
                v-else-if="isMultiSelect(i)"
                class="GmsNewReportModal__Row-Dropdown"
                multiselect
                search
                :label="getFilterPlaceholder(i, 1)"
                :items="getFilterValues(i, 1)"
                :value="filter.filterValue"
                @select="(value) => handleSelectionMultiOptions(i, value)"
              />
            </div>
          </ScrollView>
        </div>
        <div class="GmsNewReportModal__Bottom">
          <div class="GmsNewReportModal__Left">
            <Button
              class="GmsNewReportModal__AddButton"
              :mode="ButtonMode.GMS_ICON"
              :icon="IconShape.PLUS"
              @click="handleAddFilter"
            />
            <span>Add Filter</span>
            <div
              v-if="filters.length > 0"
              class="GmsNewReportModal__ClearFilters"
            >
              <Button
                class="GmsNewReportModal__AddButton"
                :mode="ButtonMode.GMS_ICON"
                :icon="IconShape.CLOSE"
                :iconColor="'#2356f6'"
                @click="handleClearFilters"
              />
              <span>Clear All Filters</span>
            </div>
          </div>
          <div class="GmsNewReportModal__Right">
            <div v-if="showRecordCount" class="GmsNewReportModal__RecordCount">
              {{ `${recordCount ? recordCount : 0} Records` }}
            </div>
            <Button
              :mode="ButtonMode.PRIMARY"
              :label="'Save Report'"
              @click="handleNext"
            />
            <div class="GmsNewReportModal__RowFoot" />
          </div>
        </div>
      </div>

      <!-- Visibility Page -->
      <div v-if="page === Pages.VISIBILITY" class="GmsNewReportModal__Content">
        <div class="GmsNewReportModal__Top">
          <div class="GmsNewReportModal__Left">
            <h2>Save New Report</h2>
            <h3>{{ error }}</h3>
          </div>
          <div class="GmsNewReportModal__Right">
            <Icon
              class="GmsNewReportModal__Close"
              :shape="IconShape.CLOSE"
              :size="16"
              @click="handleClose"
            />
          </div>
        </div>

        <div class="GmsNewReportModal__Center">
          <ScrollView>
            <div class="GmsNewReportModal__Row">
              <div class="GmsNewReportModal__RowHead">
                <div class="GmsNewReportModal__Title">Report Title</div>
              </div>
              <div class="GmsNewReportModal__RowBody">
                <input
                  class="GmsNewReportModal__Input"
                  type="text"
                  placeholder="New Custom Report"
                  v-model="reportName"
                />
                <div class="GmsNewReportModal__Title">Visibility</div>
                <Select
                  key="visibility"
                  search
                  :label="visibilityConfig.placeholder"
                  :value="visibilityValue"
                  :items="visibilityConfig.options"
                  @select="handleVisibilityChange"
                />
              </div>
            </div>

            <div v-if="isInvitationOption" class="GmsNewReportModal__Share">
              <hr />
              <div class="GmsNewReportModal__Row">
                <Select
                  class="GmsNewReportModal__Email"
                  key="Emails"
                  search
                  label="Share report with"
                  :value="emailInvitationValue"
                  :items="emailValues"
                  @select="handleEmailInviteChange"
                />
                <Button
                  class="GmsNewReportModal__Next"
                  :mode="ButtonMode.PRIMARY"
                  :label="'Invite'"
                  @click="handleInvite"
                />
              </div>
            </div>
          </ScrollView>
        </div>

        <div class="GmsNewReportModal__Bottom">
          <div class="GmsNewReportModal__Left" />
          <div class="GmsNewReportModal__Right">
            <Button
              :mode="ButtonMode.GMS_ICON"
              :label="'Cancel'"
              @click="handleCancel"
            />
            <Button
              class="GmsNewReportModal__Next"
              :mode="ButtonMode.PRIMARY"
              :label="saveButtonLabel"
              @click="handleNext"
            />
          </div>
        </div>
      </div>
    </div>
  </MountingPortal>
</template>
